    from openpyxl import load_workbook
    workbook = load_workbook(path, read_only=True, data_only=True)
    try:
        sheet = workbook.active
        out = io.StringIO()
        writer = csv.writer(out, lineterminator='\n')
        for count, cells in enumerate(sheet.iter_rows(values_only=True)):
            if count > max_rows + 1:
                break
            writer.writerow([_cell_text(c) for c in cells])
        return out.getvalue()
    finally:
        workbook.close()


def validate_users_upload(path: str, max_rows: int=MAX_ROWS) -> dict[str, Any]:
    if os.path.splitext(path)[1].lower() in EXCEL_EXTENSIONS:
        text = excel_to_csv_text(path, max_rows)
    else:
        with open(path, 'r', encoding='utf-8-sig', newline='') as handle:
            text = handle.read()
    valid, errors = import_users(text, max_rows)
    return {
        'valid_count': len(valid),
        'invalid_count': len(errors),
        'valid_users': valid,
        'invalid_rows': sorted(errors, key=lambda e: e['row']),
